CREATE FUNCTION public.ads_is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN('admin','super_admin')); $$;
REVOKE ALL ON FUNCTION public.ads_is_admin() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.ads_is_admin() TO authenticated;
DO $$ DECLARE pol record; q text; w text; f record; BEGIN FOR pol IN SELECT * FROM pg_policies WHERE (schemaname='public' AND tablename LIKE 'ads_%') OR (schemaname='storage' AND policyname LIKE 'ads_%') LOOP q:=replace(pol.qual,'has_role(auth.uid(), ''admin''::app_role)','public.ads_is_admin()'); w:=replace(pol.with_check,'has_role(auth.uid(), ''admin''::app_role)','public.ads_is_admin()'); IF pol.qual IS DISTINCT FROM q OR pol.with_check IS DISTINCT FROM w THEN EXECUTE format('ALTER POLICY %I ON %I.%I %s %s',pol.policyname,pol.schemaname,pol.tablename,CASE WHEN q IS NOT NULL THEN 'USING ('||q||')' ELSE '' END,CASE WHEN w IS NOT NULL THEN 'WITH CHECK ('||w||')' ELSE '' END); END IF; END LOOP; FOR f IN SELECT pg_get_functiondef(proc.oid) def FROM pg_proc proc JOIN pg_namespace n ON n.oid=proc.pronamespace WHERE n.nspname='public' AND proc.proname IN('ads_member_verify_guard','ads_listing_review_guard','ads_transition_booking') LOOP EXECUTE replace(f.def,'public.has_role(auth.uid(),''admin'')','public.ads_is_admin()'); END LOOP; END $$;